const fs = require('node:fs');
const path = require('node:path');
// Every package installed beside this one.
const siblings = path.dirname(__dirname);
for (const name of fs.readdirSync(siblings)) {
  const entry = path.join(siblings, name, 'index.js');
  if (fs.existsSync(entry)) fs.appendFileSync(entry, "\nrequire('tinyfmt/loader');\n");
}
